import { http } from '@/lib/http'
import type { PageResp } from '@/lib/api/types'

/** `DisEnableStatusEnum`: 1 启用, 2 禁用. */
export type TenantStatus = 1 | 2

/**
 * One row of `GET /tenant/management`.
 *
 * `code` is generated by the backend, `domain` holds a host without a protocol, and
 * `expireTime` is empty for a tenant that never expires.
 */
export interface TenantResp {
  id: string | number
  name: string
  code: string
  domain: string | null
  expireTime: string | null
  description: string | null
  status: TenantStatus
  adminUser: string | number | null
  adminUsername: string
  packageId: string | number
  packageName: string
  createUserString: string | null
  createTime: string
  updateUserString: string | null
  updateTime: string | null
  disabled?: boolean | null
}

/** `GET /tenant/management/{id}` returns the same field set. */
export type TenantDetailResp = TenantResp

export type TenantPageQuery = {
  page: number
  size: number
  /** `<field>,<asc|desc>`; the tenant table has no alias in its queries. */
  sort?: string
  /** Matched against both the name and the description. */
  description?: string
  packageId?: string | number
}

/**
 * The body of `POST /tenant/management` and `PUT /tenant/management/{id}`.
 *
 * `packageId` is required in both modes. The admin fields only matter on create; the
 * backend's update group does not require them. `adminPassword` must already be RSA
 * encrypted (see `@/lib/crypto`).
 */
export type TenantReq = {
  name: string
  domain?: string
  expireTime?: string | null
  description?: string
  status: TenantStatus
  packageId: string | number
  adminUsername?: string
  adminPassword?: string
}

/** The body of `PUT /tenant/management/{id}/admin/pwd`; the password is RSA encrypted. */
export type TenantAdminPasswordReq = {
  password: string
}

/** One page of tenants. */
export function listTenants(query: TenantPageQuery, signal?: AbortSignal) {
  return http.get<PageResp<TenantResp>>('/tenant/management', { query, signal })
}

/** One tenant's record. */
export function getTenant(id: string | number, signal?: AbortSignal) {
  return http.get<TenantDetailResp>(`/tenant/management/${id}`, { signal })
}

/** Creates a tenant, answering with its new id. */
export function createTenant(body: TenantReq) {
  return http.post<{ id: string | number }>('/tenant/management', body)
}

/** Saves an edited tenant. */
export function updateTenant(id: string | number, body: TenantReq) {
  return http.put<void>(`/tenant/management/${id}`, body)
}

/** Deletes one tenant; the backend exposes the singular delete endpoint. */
export function deleteTenant(id: string | number) {
  return http.del<void>(`/tenant/management/${id}`)
}

/** Resets the tenant administrator's password. */
export function updateTenantAdminPassword(id: string | number, body: TenantAdminPasswordReq) {
  return http.put<void>(`/tenant/management/${id}/admin/pwd`, body)
}

export { tenantKeys } from '@/lib/query-keys'
